// Fonction pour obtenir une traduction
function getMidjourneyTranslation(key, lang) {
    if (midjourneyTranslations[lang] && midjourneyTranslations[lang][key]) {
        return midjourneyTranslations[lang][key];
    }
    // Fallback à l'anglais
    if (midjourneyTranslations.en && midjourneyTranslations.en[key]) {
        return midjourneyTranslations.en[key];
    }
    return null;
}

// Appliquer les traductions midjourney
function applyMidjourneyTranslations(lang) {
    console.log('🔥 Applying midjourney translations for:', lang);

    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');

        // Seulement pour les clés midjourney
        if (key && (key.startsWith('review.midjourney.') || key.startsWith('review.common.'))) {
            const translation = getMidjourneyTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });

    console.log(`✅ Applied ${count} midjourney translations`);
}

// Auto-appliquer quand la langue change
window.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyMidjourneyTranslations(lang), 200);
});

// Appliquer au chargement
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyMidjourneyTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyMidjourneyTranslations(currentLang);
}

console.log('✅ midjourney i18n loaded');
